#!/bin/bash
set -u

CONF=/etc/nginx/sites-enabled/app
CONTENT=/srv/www/index.html
BACKUP_DIR=/var/backups/nginx

if [ ! -f "$CONTENT" ]; then
    echo "Файл $CONTENT не найден" >&2
    exit 1
fi

# nginx подключает все файлы из sites-enabled/*, поэтому резервные копии
# нельзя хранить там. Переносим старые копии, оставшиеся от предыдущих запусков.
mkdir -p "$BACKUP_DIR"
for f in /etc/nginx/sites-enabled/*.broken.*; do
    [ -e "$f" ] || continue
    mv "$f" "$BACKUP_DIR/"
done

# Резервная копия сломанной конфигурации вне sites-enabled
if [ -e "$CONF" ]; then
    cp -a "$CONF" "$BACKUP_DIR/app.broken.$(date +%Y%m%d%H%M%S)"
fi

cat > "$CONF" <<'EOF'
server {
    listen 8080;
    listen [::]:8080;
    server_name localhost;

    root /srv/www;
    index index.html;

    location = / {
        try_files /index.html =404;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF

if ! nginx -t; then
    echo "nginx -t не прошёл, запуск отменён" >&2
    exit 1
fi

if pgrep -x nginx >/dev/null 2>&1; then
    nginx -s reload || { echo "Не удалось перезагрузить nginx" >&2; exit 1; }
else
    nginx || { echo "Не удалось запустить nginx" >&2; exit 1; }
fi

sleep 1
if command -v curl >/dev/null 2>&1; then
    curl -sf http://localhost:8080/ >/dev/null && echo "OK: http://localhost:8080/ отвечает" \
        || echo "Предупреждение: http://localhost:8080/ не отвечает" >&2
fi
